package org.millenaire.common.utilities;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;public class ThreadSafeUtilities {public static class ChunkAccessException extends Exception {}public static BlockState getBlockState(Level w,int x,int y,int z)throws ChunkAccessException{throw new AssertionError("Unexpected world access");}public static Block getBlock(Level w,int x,int y,int z)throws ChunkAccessException{throw new AssertionError("Unexpected world access");}public static boolean isBlockPassable(Block b,Level w,int x,int y,int z)throws ChunkAccessException{throw new AssertionError("Unexpected world access");}}